"use client";
import { useEffect, useRef, useState, type CSSProperties } from "react";
import Link from "next/link";
import Icon from "@/components/header/icons";

/**
 * Sayfa altındaki iç link blokları — sekmeli.
 *
 * Önceki hâli tek başlıksız gridti ve yalnızca `categories` (aynı ebeveynin kategori
 * kardeşleri) basıyordu; ör. Greece sayfasında "Europe City Sightseeing Tours" gibi
 * bir üst seviyenin varyantları çıkıyor, sayfanın kendi alt kırılımları (Greece
 * Culture & Historical Tours, Athens Tours …) hiç iç link almıyordu.
 *
 * SEO notu: sekmeler yalnızca görünürlüğü değiştirir — TÜM panellerin linkleri
 * HTML'e basılır, pasif olanlar `hidden` ile gizlenir. Linkler tıklamayla fetch
 * edilseydi tarayıcı dışında hiç var olmazlar, keşfedilmezlerdi.
 */

export type RelatedLinkItem = {
  pageTitle: string;
  fullTitle?: string | null;
  pageUrl: string;
  tourCount?: number | null;
};

/** Sekme başına link sınırı. */
const MAX_PER_TAB = 20;

/**
 * Dar ekranda pill'ler tek sütuna dizilip uzun bir kuyruk oluşturuyor; mobilde
 * önce bu kadarını gösterip gerisini butona bağlıyoruz. Gizlenenler DOM'da kalır
 * (yalnızca `display:none`), yani linkler taranmaya devam eder.
 */
const MOBILE_VISIBLE = 8;

const arrowChrome: CSSProperties = {
  border: "1px solid #e2dced",
  background: "#fff",
  color: "#14101c",
  boxShadow: "0 4px 14px rgba(20,16,28,0.14), 0 1px 3px rgba(20,16,28,0.10)",
};

/** "Europe Tours" → "Europe"; sonunda "Tours" yoksa başlığa dokunmaz. */
function stripToursSuffix(title: string) {
  return title.replace(/\s+tours$/i, "").trim() || title;
}

/**
 * NOT (her iki panelde de): preflight kapalı olduğu için `[hidden]{display:none}`
 * yalnızca UA kuralıdır ve `tw-flex`/`tw-grid` onu ezer — pasif panel görünür kalır.
 * Görünürlüğü class ile kapatıyoruz; `hidden` attribute'u erişilebilirlik için duruyor.
 */
function LinkPanel({
  id,
  labelledBy,
  items,
  hidden,
}: {
  id: string;
  labelledBy: string;
  items: RelatedLinkItem[];
  hidden: boolean;
}) {
  const [expanded, setExpanded] = useState(false);

  return (
    <ul
      id={id}
      role="tabpanel"
      aria-labelledby={labelledBy}
      hidden={hidden}
      // Kompakt, saran pill'ler: eşit hücreli grid kısa başlıklarda kocaman
      // boşluklar bırakıyordu. Satır ritmini pill yüksekliği tutuyor.
      className={`tw-m-0 tw-list-none tw-flex-wrap tw-gap-3 tw-p-0 ${
        hidden ? "tw-hidden" : "tw-flex"
      }`}
    >
      {items.map((item, index) => {
        const label = item.fullTitle || item.pageTitle;
        const foldedOnMobile = !expanded && index >= MOBILE_VISIBLE;

        return (
          <li
            key={item.pageUrl}
            className={foldedOnMobile ? "tw-hidden sm:tw-block" : undefined}
          >
            <Link
              href={item.pageUrl}
              title={label}
              className="tw-group tw-inline-flex tw-items-center tw-gap-2.5 tw-rounded-full tw-border tw-border-solid tw-border-[#e8e4ef] tw-bg-white tw-py-2.5 tw-pl-4 tw-pr-3.5 tw-text-[14.5px] tw-leading-snug tw-no-underline tw-transition-all hover:tw--translate-y-px hover:tw-border-[#c7aee9] hover:tw-shadow-[0_4px_14px_rgba(133,78,201,0.16)]"
            >
              <span className="tw-font-medium tw-text-[#14101c] tw-transition-colors group-hover:tw-text-[#6d3bb0]">
                {label}
              </span>
              {!!item.tourCount && (
                <span className="tw-rounded-full tw-bg-[#f3eefb] tw-px-2 tw-py-1 tw-text-[12px] tw-font-semibold tw-text-[#6d3bb0]">
                  {item.tourCount.toLocaleString("en-US")}
                </span>
              )}
            </Link>
          </li>
        );
      })}

      {!expanded && items.length > MOBILE_VISIBLE && (
        <li className="sm:tw-hidden">
          <button
            type="button"
            onClick={() => setExpanded(true)}
            className="tw-cursor-pointer tw-rounded-full tw-border tw-border-solid tw-border-[#d9cbef] tw-bg-white tw-px-4 tw-py-2.5 tw-text-[14.5px] tw-font-semibold tw-leading-snug tw-text-[#6d3bb0]"
          >
            Show all {items.length}
          </button>
        </li>
      )}
    </ul>
  );
}

export type GuideItem = {
  id: number;
  slug: string;
  title: string;
  excerpt?: string | null;
  main_image?: string | null;
  category_name?: string | null;
};

/** Lokasyona bağlı blog yazıları — link chip'i değil, kapaklı kart. */
function GuidePanel({
  id,
  labelledBy,
  items,
  hidden,
}: {
  id: string;
  labelledBy: string;
  items: GuideItem[];
  hidden: boolean;
}) {
  return (
    <ul
      id={id}
      role="tabpanel"
      aria-labelledby={labelledBy}
      hidden={hidden}
      className={`tw-m-0 tw-list-none tw-gap-4 tw-p-0 sm:tw-grid-cols-2 lg:tw-grid-cols-3 ${
        hidden ? "tw-hidden" : "tw-grid"
      }`}
    >
      {items.map((post) => (
        <li key={post.id}>
          <Link
            href={`/blog/${post.slug}`}
            title={post.title}
            className="tw-flex tw-h-full tw-gap-3 tw-overflow-hidden tw-rounded-xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-p-3 tw-no-underline tw-transition-colors hover:tw-border-[#854ec9]"
          >
            {post.main_image && (
              // Blog kapakları dış CDN'den geliyor; next/image yerine düz img,
              // kart küçük olduğu için ölçek kaybı yok.
              // eslint-disable-next-line @next/next/no-img-element
              <img
                src={post.main_image}
                alt=""
                loading="lazy"
                className="tw-h-[72px] tw-w-[96px] tw-shrink-0 tw-rounded-lg tw-object-cover"
              />
            )}
            <span className="tw-flex tw-flex-col tw-gap-1">
              {post.category_name && (
                <span className="tw-text-[12px] tw-font-semibold tw-uppercase tw-tracking-wide tw-text-[#854ec9]">
                  {post.category_name}
                </span>
              )}
              <span className="tw-line-clamp-3 tw-text-[15px] tw-font-medium tw-leading-snug tw-text-[#14101c]">
                {post.title}
              </span>
            </span>
          </Link>
        </li>
      ))}
    </ul>
  );
}

export default function RelatedLinks({
  title,
  parentTitle,
  currentUrl,
  childCategories,
  childPages,
  pages,
  pagesParentTitle,
  categories,
  guides,
}: {
  title: string;
  parentTitle?: string | null;
  currentUrl: string;
  childCategories?: RelatedLinkItem[] | null;
  childPages?: RelatedLinkItem[] | null;
  /** Aynı seviyedeki destinasyon sayfaları; şehir+kategori sayfasında ülkenin şehirleri. */
  pages?: RelatedLinkItem[] | null;
  /** `pages` listesinin ebeveyni — sekme başlığı bundan kurulur. */
  pagesParentTitle?: string | null;
  categories?: RelatedLinkItem[] | null;
  guides?: GuideItem[] | null;
}) {
  const parent = parentTitle ? stripToursSuffix(parentTitle) : null;
  const pagesParent = pagesParentTitle ? stripToursSuffix(pagesParentTitle) : null;

  const clean = (items?: RelatedLinkItem[] | null) =>
    (items ?? [])
      .filter((item) => item.pageUrl && item.pageUrl !== currentUrl)
      .slice(0, MAX_PER_TAB);

  // En spesifik kümeden en genele: kendi kategorileri → kendi destinasyonları →
  // kardeş destinasyonlar → kardeş kategoriler → en sonda blog yazıları.
  const guideItems = (guides ?? []).slice(0, 6);
  const destinationLabel = stripToursSuffix(title);

  // `pages` listesinin ebeveyni doğrudan ebeveynle aynıysa liste bu sayfayla aynı
  // seviyededir; farklıysa apiv3 bir üst seviyeye çıkmış demektir.
  const pagesAreSiblings = !!pagesParent && !!parent && pagesParent === parent;

  const nearbyTab = pagesParent
    ? {
        key: "nearby",
        label: `More Destinations in ${pagesParent}`,
        kind: "links" as const,
        items: clean(pages),
      }
    : null;

  const parentStylesTab = parent
    ? {
        key: "parent-styles",
        label: `${parent} by Travel Style`,
        kind: "links" as const,
        items: clean(categories),
      }
    : null;

  const tabs: {
    key: string;
    label: string;
    kind: "links" | "guides";
    items: RelatedLinkItem[];
    guides?: GuideItem[];
  }[] = [
    { key: "styles", label: `${title} by Travel Style`, kind: "links" as const, items: clean(childCategories) },
    { key: "destinations", label: `${title} by Destination`, kind: "links" as const, items: clean(childPages) },
    // Sonra kardeş kümeler. Sıra "yakınlık"a göre: aynı seviyedeki kardeşler,
    // bir üst seviyeye çıkan listeden önce gelir. Şehir+kategori sayfasında
    // (ör. Istanbul New Year) `pages` ülkenin şehirlerine çıktığı için oradaki
    // en yakın küme aynı şehrin diğer stilleridir.
    ...((pagesAreSiblings
      ? [nearbyTab, parentStylesTab]
      : [parentStylesTab, nearbyTab]
    ).filter((tab) => tab !== null) as {
      key: string;
      label: string;
      kind: "links";
      items: RelatedLinkItem[];
    }[]),
    // Blog her zaman en sonda: hangi link kümelerinin dolu olduğu sayfadan sayfaya
    // değişiyor ve araya konursa boş kümeler elendiğinde başa geçip varsayılan
    // aktif sekme oluyordu. Öncelik tur sayfalarına giden linklerde.
    {
      key: "guides",
      label: `${destinationLabel} Travel Guides`,
      kind: "guides" as const,
      items: [] as RelatedLinkItem[],
      guides: guideItems,
    },
  ].filter((tab) => (tab.kind === "guides" ? (tab.guides?.length ?? 0) > 0 : tab.items.length > 0));

  const [active, setActive] = useState(0);
  const stripRef = useRef<HTMLDivElement>(null);
  const [showLeft, setShowLeft] = useState(false);
  const [showRight, setShowRight] = useState(false);

  useEffect(() => {
    const el = stripRef.current;
    if (!el) return;

    const sync = () => {
      setShowLeft(el.scrollLeft > 4);
      setShowRight(el.scrollLeft + el.clientWidth < el.scrollWidth - 4);
    };

    sync();
    el.addEventListener("scroll", sync, { passive: true });
    window.addEventListener("resize", sync);
    return () => {
      el.removeEventListener("scroll", sync);
      window.removeEventListener("resize", sync);
    };
  }, [tabs.length]);

  if (tabs.length === 0) return null;

  const scrollByDir = (dir: number) => {
    const el = stripRef.current;
    if (el) el.scrollBy({ left: dir * el.clientWidth * 0.7, behavior: "smooth" });
  };

  const activeTab = tabs[Math.min(active, tabs.length - 1)];

  return (
    <section
      aria-label="Related tour pages"
      className="tw-rounded-2xl tw-border tw-border-solid tw-border-[#f0edf5] tw-bg-[#fbfafd] tw-p-5 tw-font-display sm:tw-p-7"
    >
      <h2 className="tw-mb-6 tw-text-[22px] tw-font-bold tw-tracking-tight tw-text-[#14101c]">
        Explore {title}
      </h2>

      <div className="tw-relative">
        {showLeft && (
          <>
            <span
              aria-hidden
              className="tw-pointer-events-none tw-absolute tw-left-0 tw-top-0 tw-bottom-0 tw-z-[1] tw-w-10"
              style={{ background: "linear-gradient(to right, #fbfafd 35%, rgba(251,250,253,0))" }}
            />
            <button
              type="button"
              onClick={() => scrollByDir(-1)}
              aria-label="Scroll tabs left"
              className="tw-grid tw-h-8 tw-w-8 tw-cursor-pointer tw-place-items-center tw-rounded-full tw-z-[2]"
              style={{ position: "absolute", left: 0, top: "40%", transform: "translateY(-50%)", ...arrowChrome }}
            >
              <Icon name="chevDown" size={16} stroke={2.4} className="tw-rotate-90" />
            </button>
          </>
        )}

        <div
          ref={stripRef}
          role="tablist"
          aria-label="Related page groups"
          className="tw-flex tw-gap-6 tw-overflow-x-auto tw-whitespace-nowrap tw-border-0 tw-border-b tw-border-solid tw-border-[#e9e5f0] [scrollbar-width:none] [&::-webkit-scrollbar]:tw-hidden"
        >
          {tabs.map((tab, index) => {
            const isActive = tab.key === activeTab.key;
            return (
              <button
                key={tab.key}
                id={`related-tab-${tab.key}`}
                role="tab"
                type="button"
                aria-selected={isActive}
                aria-controls={`related-panel-${tab.key}`}
                tabIndex={isActive ? 0 : -1}
                onClick={() => setActive(index)}
                onKeyDown={(event) => {
                  if (event.key !== "ArrowRight" && event.key !== "ArrowLeft") return;
                  event.preventDefault();
                  const next =
                    (index + (event.key === "ArrowRight" ? 1 : -1) + tabs.length) % tabs.length;
                  setActive(next);
                  document.getElementById(`related-tab-${tabs[next].key}`)?.focus();
                }}
                className={`tw-cursor-pointer tw-border-0 tw-bg-transparent tw-px-0 tw-pb-3 tw-text-[15px] tw-transition-colors ${
                  isActive
                    ? "tw-font-bold tw-text-[#14101c] tw-shadow-[inset_0_-2px_0_0_#854ec9]"
                    : "tw-font-medium tw-text-[#5d556c] hover:tw-text-[#14101c]"
                }`}
              >
                {tab.label}
              </button>
            );
          })}
        </div>

        {showRight && (
          <>
            <span
              aria-hidden
              className="tw-pointer-events-none tw-absolute tw-right-0 tw-top-0 tw-bottom-0 tw-z-[1] tw-w-10"
              style={{ background: "linear-gradient(to left, #fbfafd 35%, rgba(251,250,253,0))" }}
            />
            <button
              type="button"
              onClick={() => scrollByDir(1)}
              aria-label="Scroll tabs right"
              className="tw-grid tw-h-8 tw-w-8 tw-cursor-pointer tw-place-items-center tw-rounded-full tw-z-[2]"
              style={{ position: "absolute", right: 0, top: "40%", transform: "translateY(-50%)", ...arrowChrome }}
            >
              <Icon name="chevDown" size={16} stroke={2.4} className="tw--rotate-90" />
            </button>
          </>
        )}
      </div>

      <div className="tw-mt-5">
        {tabs.map((tab) =>
          tab.kind === "guides" ? (
            <GuidePanel
              key={tab.key}
              id={`related-panel-${tab.key}`}
              labelledBy={`related-tab-${tab.key}`}
              items={tab.guides ?? []}
              hidden={tab.key !== activeTab.key}
            />
          ) : (
            <LinkPanel
              key={tab.key}
              id={`related-panel-${tab.key}`}
              labelledBy={`related-tab-${tab.key}`}
              items={tab.items}
              hidden={tab.key !== activeTab.key}
            />
          ),
        )}
      </div>
    </section>
  );
}
