"use client";
import { useState, useRef, useEffect } from "react";

// Section heading is rendered by the parent as an <h2>, so demote the headings
// coming from the CMS content one level to keep the document outline correct.
function demoteHeadings(html: string) {
  return html.replace(
    /<(\/?)h[12]([^>]*)>/gi,
    (_match, slash, attrs) => `<${slash}h3${slash ? "" : attrs}>`
  );
}

export default function ReadMoreText({ html }: { html: string }) {
  const [isExpanded, setIsExpanded] = useState(false);
  const [shouldTruncate, setShouldTruncate] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  const maxHeight = 300; // pixels

  useEffect(() => {
    if (containerRef.current) {
      // Check if content exceeds max height
      const scrollHeight = containerRef.current.scrollHeight;
      setShouldTruncate(scrollHeight > maxHeight);
    }
  }, []);

  return (
    <div className="tw-relative">
      <div
        ref={containerRef}
        className="tw-overflow-hidden tw-text-base tw-leading-relaxed tw-text-[#5d556c] tw-transition-[max-height] tw-duration-300 tw-ease-in-out [&_h3]:tw-mb-2 [&_h3]:tw-mt-6 [&_h3]:tw-font-display [&_h3]:tw-text-[17px] [&_h3]:tw-font-semibold [&_h3]:tw-text-[#14101c]"
        style={{ maxHeight: isExpanded ? "none" : `${maxHeight}px` }}
        dangerouslySetInnerHTML={{ __html: demoteHeadings(html) }}
      ></div>

      {shouldTruncate && !isExpanded && (
        <div className="tw-pointer-events-none tw-absolute tw-inset-x-0 tw-bottom-0 tw-z-[1] tw-h-24 tw-bg-gradient-to-b tw-from-transparent tw-to-white" />
      )}

      {shouldTruncate && !isExpanded && (
        <div className="tw-relative tw-z-[2] tw--mt-8 tw-text-center">
          <button
            onClick={() => setIsExpanded(true)}
            className="tw-cursor-pointer tw-rounded-full tw-border tw-border-solid tw-border-[#854ec9] tw-bg-white tw-px-5 tw-py-2 tw-text-sm tw-font-semibold tw-text-[#854ec9] tw-transition-colors hover:tw-bg-[#854ec9] hover:tw-text-white"
          >
            Read More
          </button>
        </div>
      )}
    </div>
  );
}
