"use client";
import { useState } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faChevronDown } from "@fortawesome/free-solid-svg-icons";

type FaqItem = {
  question: string;
  answer: string;
};

type FaqAccordionProps = {
  faq?: FaqItem[] | null;
};

export default function FaqAccordion({ faq }: FaqAccordionProps) {
  const [openIdx, setOpenIdx] = useState<number | null>(null);

  if (!faq || faq.length === 0) return null;

  return (
    <div className="tw-mt-12 tw-font-display">
      <h2 className="tw-mb-4 tw-text-lg tw-font-bold tw-tracking-tight tw-text-[#14101c]">
        Frequently Asked Questions
      </h2>
      <div className="tw-flex tw-flex-col tw-gap-3">
        {faq.map((item, index) => {
          const isOpen = openIdx === index;
          return (
            <div
              key={index}
              className="tw-overflow-hidden tw-rounded-xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white"
            >
              <h3 className="tw-m-0">
                <button
                  type="button"
                  onClick={() => setOpenIdx(isOpen ? null : index)}
                  aria-expanded={isOpen}
                  className="tw-flex tw-w-full tw-items-center tw-justify-between tw-gap-4 tw-border-0 tw-bg-transparent tw-px-5 tw-py-4 tw-text-left tw-text-[15px] tw-font-semibold tw-text-[#14101c] tw-transition-colors hover:tw-bg-[#faf9fc]"
                >
                  {item.question}
                  <FontAwesomeIcon
                    icon={faChevronDown}
                    className={`tw-shrink-0 tw-text-[#854ec9] tw-transition-transform tw-duration-200 ${isOpen ? "tw-rotate-180" : ""}`}
                  />
                </button>
              </h3>
              {isOpen && (
                <div
                  className="tw-border-0 tw-border-t tw-border-solid tw-border-[#f0edf5] tw-px-5 tw-py-4 tw-text-sm tw-leading-relaxed tw-text-[#5d556c]"
                  dangerouslySetInnerHTML={{ __html: item.answer }}
                />
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}
